function validate([nums, d]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer from 1 to 10^9.';
  if (!Number.isInteger(d) || d < 1 || d > 1000000000) return 'd is an integer from 1 to 10^9.';
  return null;
}

