function divisibleTripletCount(nums, d) {
  const seen = new Map();
  let total = 0;

  for (let j = 0; j < nums.length; j++) {
    for (let k = j + 1; k < nums.length; k++) {
      const need = (d - ((nums[j] + nums[k]) % d)) % d;
      total += seen.get(need) || 0;
    }
    const rem = nums[j] % d;
    seen.set(rem, (seen.get(rem) || 0) + 1);
  }
  return total;
}

