function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1000000000;
  const n = size === 'large' ? pick(800, 1000) : pick(1, 9);
  const choices = size === 'large' ? [1, 2, 3, 7, 100, 99991, LIMIT, pick(1, LIMIT)] : [1, 2, 3, 4, 5, 6, 10, LIMIT, pick(1, 20)];
  const d = choices[pick(0, choices.length - 1)];
  // Draw remainders from a small pool so that many triplets can line up, then lift them by multiples of d.
  const pool = Array.from({ length: pick(1, 5) }, () => pick(0, d - 1));
  const nums = Array.from({ length: n }, () => {
    const rem = pool[pick(0, pool.length - 1)];
    const value = rem + d * pick(0, Math.floor((LIMIT - rem) / d));
    return value === 0 ? d : value;
  });
  return [nums, d];
}
